const itemById = Object.fromEntries(PRACTICE_DATA.map(x => [x.id, x]));

function escHtml(s){return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

function renderPractice(widget){
  const ids = JSON.parse(widget.dataset.itemIds || '[]');
  let page = Number(widget.dataset.page || 0);
  const perPage = 3;
  const totalPages = Math.ceil(ids.length / perPage);
  if(page < 0) page = 0;
  if(page >= totalPages) page = totalPages - 1;
  widget.dataset.page = page;
  const slot = widget.querySelector('.practice-items');
  slot.innerHTML = '';
  ids.slice(page*perPage, page*perPage + perPage).forEach((id, idx) => {
    const item = itemById[id];
    const options = [item.option_a, item.option_b, item.option_c, item.option_d].filter(x => x !== undefined && String(x).trim() !== '');
    const card = document.createElement('article');
    card.className = 'practice-card';
    card.dataset.itemId = id;
    card.dataset.correct = item.correct_answer;
    card.innerHTML = `
      <h5>${escHtml(item.question)}</h5>
      <div class="choices">
        ${options.map((opt, oi) => `
          <label class="choice">
            <input type="radio" name="${escHtml(id)}" value="${escHtml(opt)}">
            <span>${escHtml(opt)}</span>
          </label>
        `).join('')}
      </div>
      <div class="feedback" aria-live="polite"></div>
      <div class="wrong-actions" hidden>
        <button type="button" class="try-btn">Try again</button>
        <button type="button" class="answer-btn">Correct Answer</button>
      </div>
    `;
    slot.appendChild(card);
  });
  widget.querySelector('.page-status').textContent = `Page ${page+1} of ${totalPages}`;
  widget.querySelector('.prev-btn').disabled = page === 0;
  widget.querySelector('.next-btn').disabled = page === totalPages - 1;
}

function checkPractice(widget){
  widget.querySelectorAll('.practice-card').forEach(card => {
    const id = card.dataset.itemId;
    const item = itemById[id];
    const chosen = card.querySelector('input[type="radio"]:checked');
    const feedback = card.querySelector('.feedback');
    const actions = card.querySelector('.wrong-actions');
    actions.hidden = true;
    feedback.className = 'feedback';
    if(!chosen){
      feedback.textContent = 'Choose an answer first.';
      feedback.classList.add('blank');
      return;
    }
    if(chosen.value === item.correct_answer){
      feedback.textContent = item.feedback_correct || 'Correct.';
      feedback.classList.add('correct');
      actions.hidden = true;
    }else{
      feedback.textContent = item.feedback_incorrect || 'Try again.';
      feedback.classList.add('wrong');
      actions.hidden = false;
    }
  });
}

function resetPractice(widget){
  widget.querySelectorAll('.practice-card').forEach(card => {
    card.querySelectorAll('input[type="radio"]').forEach(i => i.checked = false);
    const feedback = card.querySelector('.feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';
    card.querySelector('.wrong-actions').hidden = true;
  });
}

document.addEventListener('click', e => {
  const widget = e.target.closest('.practice-widget');
  if(e.target.matches('.check-btn')) checkPractice(widget);
  if(e.target.matches('.reset-btn')) resetPractice(widget);
  if(e.target.matches('.prev-btn')) { widget.dataset.page = Number(widget.dataset.page || 0)-1; renderPractice(widget); }
  if(e.target.matches('.next-btn')) { widget.dataset.page = Number(widget.dataset.page || 0)+1; renderPractice(widget); }
  if(e.target.matches('.try-btn')) {
    const card = e.target.closest('.practice-card');
    card.querySelectorAll('input[type="radio"]').forEach(i => i.checked = false);
    const feedback = card.querySelector('.feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';
    card.querySelector('.wrong-actions').hidden = true;
  }
  if(e.target.matches('.answer-btn')) {
    const card = e.target.closest('.practice-card');
    const item = itemById[card.dataset.itemId];
    const feedback = card.querySelector('.feedback');
    feedback.textContent = `Correct Answer: ${item.correct_answer}`;
    feedback.className = 'feedback wrong';
  }
  if(e.target.matches('.zoom-btn')) {
    const modal = document.querySelector('.modal');
    modal.querySelector('img').src = e.target.dataset.img;
    modal.classList.add('open');
  }
  if(e.target.matches('.modal-close') || e.target.classList.contains('modal')){
    document.querySelector('.modal').classList.remove('open');
  }
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.practice-widget').forEach(renderPractice);
  document.querySelectorAll('.wrong-actions').forEach(a => a.hidden = true);
});

document.addEventListener('click', e => { if(e.target.matches('.audio-btn')) flwPlayUnitAudio(e.target); });
